def parse_duration(text: str) -> timedelta:
    """Parse '1h30m', '45s' or '2d' into a timedelta."""
    return timedelta(seconds=int(text))

def retry(call: Callable[[], T], attempts: int = 3) -> T:
    """Call `call`, retrying up to `attempts` times when it raises."""
    return call()

def is_overdue(order: Order, today: date) -> bool:
    """Whether the order is past its due date and unpaid."""
    return order.due < today and not order.paid

def words(text: str) -> tuple[str, ...]:
    """An identifier's or a term's words, lower-cased: CamelCase, snake_case
    and spaced spellings of one name give the same words."""
    return tuple(w.lower() for w in WORD.findall(text))

def normalised(line: str) -> str:
    """An offending line as identity reads it: every run of whitespace one
    space, none at either end."""
    return " ".join(line.split())
